-- Quejas, evaluaciones, entrevistas, bitácora de auditoría, reportes, respaldos y cierres de caja.


SELECT u.id_usuario, d::date, x.est,
       CASE WHEN x.c < .3 THEN (ARRAY['Todo excelente','Muy buena atención','El pollo estuvo perfecto','Un poco de espera, pero valió la pena','Me gustaría más opciones de salsas','Volveré pronto'])[1 + floor(x.c * 20)::int % 6] END,
       d + time '20:00' + x.c * interval '90 minutes'
FROM usuario u, generate_series(CURRENT_DATE - 45, CURRENT_DATE, interval '1 day') d,
LATERAL (SELECT random() AS r, random() AS c, CASE WHEN random() < .45 THEN 5 WHEN random() < .64 THEN 4 WHEN random() < .6 THEN 3 WHEN random() < .5 THEN 2 ELSE 1 END AS est) x
WHERE u.id_usuario BETWEEN 9 AND 36 AND x.r < 0.20 AND d + time '20:00' < now();





VALUES ('EMP-0300', 'Yenny Maldonado Torrez', 'Mesera', 'TARDE', 2500, 'ACTIVO', CURRENT_DATE - 6, '71234514', NULL, 6);

SELECT d + t.hora, t.tipo, COALESCE(SUM(p.total), 0), COUNT(p.id_pedido)::int, CASE WHEN t.hora < time '16:00' THEN 7 ELSE 8 END,
       CASE t.tipo WHEN 'INTERMEDIO' THEN 'Cierre intermedio de caja del turno mañana' ELSE 'Cierre final del día' END
FROM generate_series(CURRENT_DATE - 14, CURRENT_DATE, interval '1 day') d
CROSS JOIN (VALUES (time '15:30', 'INTERMEDIO'), (time '22:30', 'FINAL')) AS t(hora, tipo)
LEFT JOIN pedido p ON p.fecha_turno = d::date AND p.estado <> 'CANCELADO' AND p.creado_en < d + t.hora
WHERE d + t.hora < now()
GROUP BY d, t.hora, t.tipo;

SELECT t, 'kingtokky_' || to_char(t, 'YYYYMMDD_HH24MI') || '.sql', (2400000 + random() * 700000)::bigint,
       CASE WHEN n = 17 THEN 'FALLIDO' ELSE 'EXITOSO' END, (900 + random() * 1800)::bigint,
       CASE WHEN n = 17 THEN 'Tiempo de espera agotado al conectar con la base de datos' ELSE 'Respaldo lógico completado' END
FROM (SELECT d + h AS t, row_number() OVER (ORDER BY d + h) n FROM generate_series(CURRENT_DATE - 14, CURRENT_DATE, interval '1 day') d,
      (VALUES (time '03:00'), (time '15:00')) AS x(h)) s WHERE t < now();

SELECT 'Ventas del mes ' || to_char(m, 'YYYY-MM'), 'VENTAS_MENSUAL', f.fmt, to_char(m, 'YYYY-MM'), m + interval '1 month' + time '06:00', 1, (180000 + random() * 90000)::bigint, true
FROM generate_series(date_trunc('month', CURRENT_DATE) - interval '2 months', date_trunc('month', CURRENT_DATE) - interval '1 month', interval '1 month') m,
     (VALUES ('PDF'), ('XLSX')) AS f(fmt);
SELECT 'Auditoría semanal ' || to_char(d, 'DD/MM/YYYY'), 'AUDITORIA', 'PDF', to_char(d, 'IYYY-"W"IW'), d + time '23:30', NULL, (90000 + random() * 50000)::bigint, true
FROM generate_series(CURRENT_DATE - 35, CURRENT_DATE, interval '7 days') d WHERE d + time '23:30' < now();


SELECT p.cancelado_en, 'ANULACION_COMANDA', 'Despacho', u.id_usuario, u.nombre_usuario, 'ROL-DESPACHO', 'Anuló la comanda #' || p.numero_turno || ': ' || p.motivo_cancelacion, 'ALERTA'
FROM pedido p JOIN usuario u ON u.id_usuario = p.id_registrado_por WHERE p.estado = 'CANCELADO';
SELECT m.fecha_hora, 'AJUSTE_STOCK', 'Inventario', u.id_usuario, u.nombre_usuario, 'ROL-GERENTE',
       'Registró merma de ' || m.cantidad || ' ' || i.unidad_medida || ' de ' || i.nombre || ' (' || lower(m.motivo) || ')', 'INFO'
FROM merma m JOIN insumo i USING (id_insumo) JOIN usuario u ON u.id_usuario = m.id_usuario;
SELECT m.fecha_hora, 'AJUSTE_STOCK', 'Inventario', u.id_usuario, u.nombre_usuario, 'ROL-GERENTE',
       'Registró entrada de ' || m.variacion || ' ' || i.unidad_medida || ' de ' || i.nombre || ' (doc. ' || m.documento || ')', 'INFO'
FROM movimiento_inventario m JOIN insumo i USING (id_insumo) JOIN usuario u ON u.id_usuario = m.id_usuario WHERE m.tipo = 'ENTRADA' AND m.id_movimiento % 5 = 0;
SELECT c.fecha_hora, 'CIERRE_CAJA', 'Caja', u.id_usuario, u.nombre_usuario, 'ROL-DESPACHO',
       'Registró cierre ' || lower(c.tipo) || ' de caja por Bs ' || c.total_ventas, 'INFO'
FROM cierre_caja c JOIN usuario u ON u.id_usuario = c.id_usuario;
SELECT r.fecha_hora, 'RESPALDO', 'Respaldo', NULL, 'Sistema', NULL,
       CASE r.estado WHEN 'EXITOSO' THEN 'Respaldo automático generado: ' || r.archivo ELSE 'Falló el respaldo automático: ' || r.mensaje END,
       CASE r.estado WHEN 'EXITOSO' THEN 'INFO' ELSE 'CRITICO' END
FROM respaldo r;
SELECT r.cancelada_en, 'RESERVA', 'Reservas', NULL, 'Sistema', NULL, 'Reserva ' || r.codigo || ' cancelada automáticamente por falta de pago en caja', 'ALERTA'
FROM reserva r WHERE r.estado = 'CANCELADA_AUTO';
SELECT k.cerrado_en, 'AJUSTE_STOCK', 'Inventario', 5, 'gerente', 'ROL-GERENTE', 'Cerró el control de inventario ' || lower(k.tipo) || ' #' || k.id_control || ' con ajustes de conteo físico', 'INFO'
FROM control_inventario k WHERE k.estado = 'CERRADO';

DELETE FROM bitacora WHERE fecha_hora > now();
SELECT setval(pg_get_serial_sequence('bitacora','id_bitacora'), (SELECT MAX(id_bitacora) FROM bitacora));
SELECT setval(pg_get_serial_sequence('queja','id_queja'), (SELECT MAX(id_queja) FROM queja));
SELECT setval(pg_get_serial_sequence('vacante','id_vacante'), (SELECT MAX(id_vacante) FROM vacante));
SELECT setval(pg_get_serial_sequence('postulante','id_postulante'), (SELECT MAX(id_postulante) FROM postulante));
SELECT setval(pg_get_serial_sequence('empleado','id_empleado'), (SELECT MAX(id_empleado) FROM empleado));
